WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.ViewCount, p.CreationDate, p.Score, p.AnswerCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS rn, p.OwnerUserId FROM Posts AS p JOIN Users AS u ON p.OwnerUserId = u.Id WHERE u.Reputation > 1000), UserBadges AS (SELECT b.UserId, COUNT(*) AS BadgeCount, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Badges AS b GROUP BY b.UserId), PostVoteStats AS (SELECT v.PostId, SUM(CASE WHEN v.VoteTypeId = 2 THEN 1 ELSE 0 END) AS UpVotes, SUM(CASE WHEN v.VoteTypeId = 3 THEN 1 ELSE 0 END) AS DownVotes FROM Votes AS v GROUP BY v.PostId) SELECT rp.PostId, rp.Title, rp.ViewCount, rp.CreationDate, rp.Score, rp.AnswerCount, COALESCE(ub.BadgeCount, 0) AS BadgeCount, COALESCE(ub.BadgeNames, '') AS BadgeNames, COALESCE(pvs.UpVotes, 0) AS UpVotes, COALESCE(pvs.DownVotes, 0) AS DownVotes, COALESCE(pvs.UpVotes, 0) - COALESCE(pvs.DownVotes, 0) AS NetVotes FROM RankedPosts AS rp LEFT JOIN UserBadges AS ub ON rp.OwnerUserId = ub.UserId LEFT JOIN PostVoteStats AS pvs ON rp.PostId = pvs.PostId WHERE rp.rn = 1 ORDER BY rp.Score DESC NULLS FIRST, rp.CreationDate DESC NULLS FIRST FETCH FIRST 100 ROWS ONLY